smoke:
set -eu
unset CARGO_TARGET_DIR
export PATH="$PATH${HOME:+:$HOME/.cargo/bin}"
set -- unpacked/berylx-*
test "$#" -eq 1 && test -d "$1"
crate_dir="$1"
mkdir -p consumer/src
cat > consumer/Cargo.toml <<EOF
[package]
name = "berylx-smoke-consumer"
version = "0.1.0"
edition = "2021"

[dependencies]
berylx = { path = "../$crate_dir" }
EOF
cat > consumer/src/main.rs <<'EOF'
use std::num::NonZeroUsize;
use berylx::prelude::{branch, run_with, task, DryRun, Error, Merge, Outcome, Real, Retry, Root};
use berylx::{to_dot, to_mermaid, Audit};

#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct State {
    charged: u32,
    refunded: u32,
    reserved: bool,
    invoiced: bool,
    notified: bool,
}

impl Merge for State {
    fn merge(left: Self, right: Self) -> Self {
        Self {
            charged: left.charged.max(right.charged),
            refunded: left.refunded.max(right.refunded),
            reserved: left.reserved || right.reserved,
            invoiced: left.invoiced || right.invoiced,
            notified: left.notified || right.notified,
        }
    }
}

fn main() {
    let charge = task("charge", |mut s: State| {
        s.charged = 100;
        Outcome::Ok(s)
    });
    let reserve = task("reserve", |mut s: State| {
        s.reserved = true;
        Outcome::Ok(s)
    });
    let invoice = task("invoice", |mut s: State| {
        s.invoiced = true;
        Outcome::Ok(s)
    });
    let ship = task("ship", |s: State| {
        Outcome::Err(s, Error::new("no_courier", "unavailable"))
    });
    let notify = task("notify", |mut s: State| {
        s.notified = true;
        Outcome::Ok(s)
    });

    let failing = charge.clone().then(ship.clone());
    let mut failed_root = Root::new(State::default());
    let failed = failed_root.run(&failing);
    assert!(failed.is_err());
    assert_eq!(failed.state().charged, 100);
    assert_eq!(failed_root.state().charged, 0);
    let err = failed.error().expect("expected error");
    assert_eq!(err.code(), "no_courier");
    assert_eq!(err.failed_node(), Some("ship"));

    let wf = charge
        .then(reserve.par(invoice).with_workers(NonZeroUsize::new(2).unwrap()))
        .then(ship)
        .rescue_with("compensate", |mut s: State, e| {
            assert_eq!(e.code(), "no_courier");
            assert_eq!(s.charged, 100);
            assert!(s.reserved && s.invoiced);
            s.refunded = s.charged;
            s.reserved = false;
            Outcome::Ok(s)
        })
        .then(
            branch()
                .when("refunded", |s: &State| s.refunded > 0, notify.clone())
                .otherwise(notify),
        );

    assert!(to_mermaid(&wf).starts_with("flowchart TD"));
    assert!(to_dot(&wf).contains("digraph berylx"));

    let dry = DryRun::new();
    let mut root = Root::new(State::default());
    assert!(root.run_with(&wf, &dry).is_ok());
    assert_eq!(root.state(), &State::default());
    let mut planned = dry.planned();
    planned.sort();
    assert_eq!(planned, vec!["charge", "invoice", "notify", "reserve", "ship"]);

    let audit = Audit::new(Real);
    let out = root.run_with(&wf, &audit);
    assert!(out.is_ok());
    assert_eq!(
        root.state(),
        &State {
            charged: 100,
            refunded: 100,
            reserved: false,
            invoiced: true,
            notified: true,
        }
    );
    let mut seen = audit.seen();
    seen.sort();
    assert_eq!(seen, vec!["charge", "invoice", "notify", "reserve", "ship"]);

    let flaky = task("flaky", |n: u32| {
        if n < 2 {
            Outcome::Err(n + 1, Error::new("transient", "retry"))
        } else {
            Outcome::Ok(n)
        }
    });
    assert_eq!(run_with(&flaky, 0, &Retry::without_backoff(Real, 3)).ok(), Some(2));

    println!("BERYLX_SMOKE_OK");
}
EOF
cargo run --offline --manifest-path consumer/Cargo.toml --target-dir "$TMPDIR/cargo-smoke-target"
